old_scroll = "function renderShop(){if(!panel)return;const scroll=dialog.scrollTop;balance.textContent=`🪙 ${coinsOf(currentData)} コイン`;renderPreview();renderTabs();if(activeTab==='custom')renderCustomPanel();else renderItemPanel(activeTab);requestAnimationFrame(()=>{dialog.scrollTop=scroll;});}"
new_scroll = "function renderShop(){if(!panel)return;const scroll=panel.scrollTop;balance.textContent=`🪙 ${coinsOf(currentData)} コイン`;renderPreview();renderTabs();if(activeTab==='custom')renderCustomPanel();else renderItemPanel(activeTab);requestAnimationFrame(()=>{panel.scrollTop=scroll;});}"
